INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1601, 'Exodus 6:1', 'Exodus', 6, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”اوس به تۀ وګورې چې زۀ د فِرعون سره څۀ کوم. زۀ به خپل زور سره هغه دې ته مجبور کړم چې زما خلق تلو ته پرېږدى، زۀ به د خپل لوئ طاقت نه کار واخلم چې فِرعون هغوئ د مُلک مصر نه وشړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1602, 'Exodus 6:2', 'Exodus', 6, 2, '&nbsp;خُدائ پاک موسىٰ ته وفرمائيل، ”زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1603, 'Exodus 6:3', 'Exodus', 6, 3, '&nbsp;زۀ د قادر خُدائ په توګه اِبراهيم، اِسحاق او يعقوب ته راڅرګند شوم، خو ما خپل ځان په هغوئ باندې د خپل پاک نوم ”مالِک خُدائ“ په توګه ونۀ پېژندلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1604, 'Exodus 6:4', 'Exodus', 6, 4, '&nbsp;ما د هغوئ سره د کنعان مُلک ورکولو لوظ هم وکړو، هغه مُلک په کوم کښې چې دوئ د مسافرو په شان اوسېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1605, 'Exodus 6:5', 'Exodus', 6, 5, '&nbsp;اوس ما د بنى اِسرائيلو فرياد اورېدلے دے ځکه چې مِصريان د دوئ نه د نوکرانو په شان کار اخلى. زۀ به د دوئ سره خپل لوظ پوره کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1606, 'Exodus 6:6', 'Exodus', 6, 6, '&nbsp;نو بنى اِسرائيلو ته ووايه چې زۀ هغوئ ته وايم چې زۀ مالِک خُدائ يم، زۀ به تاسو بچ کړم او زۀ به تاسو د مِصريانو د غلامۍ نه آزاد کړم. زۀ به د خپل لوئ طاقت نه کار واخلم او مِصريانو له به سخته سزا ورکړم او زۀ به تاسو خلاص کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1607, 'Exodus 6:7', 'Exodus', 6, 7, '&nbsp;زۀ به تاسو خپل خلق جوړ کړم او زۀ به ستاسو خُدائ پاک يم. تاسو ته به پته ولګى چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم چې کله زۀ تاسو په مِصر کښې د غلامۍ نه آزاد کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1608, 'Exodus 6:8', 'Exodus', 6, 8, '&nbsp;زۀ به تاسو هغه مُلک ته راولم چې د کوم ما اِبراهيم، اِسحاق او يعقوب له د ورکولو پوخ لوظ کړے وو، دا مُلک به ستاسو ميراث وى. زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1609, 'Exodus 6:9', 'Exodus', 6, 9, '&nbsp;موسىٰ بنى اِسرائيلو ته دا وفرمائيل خو دوئ د هغۀ خبره وانۀ ورېدله، ځکه چې د هغوئ د سختې غلامۍ په وجه دوئ همت بائيللے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1610, 'Exodus 6:10', 'Exodus', 6, 10, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1611, 'Exodus 6:11', 'Exodus', 6, 11, '&nbsp;”لاړ شه او د مِصر بادشاه فِرعون ته ووايه چې هغه دې بنى اِسرائيل د دې مُلک نه تلو ته پرېږدى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1612, 'Exodus 6:12', 'Exodus', 6, 12, '&nbsp;خو موسىٰ ورته وفرمائيل، ”بنى اِسرائيل چې زما خبره نۀ اورى، نو فِرعون به يې څنګه واورى؟ زۀ خو په خبرو کولو کښې تکړه نۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1613, 'Exodus 6:13', 'Exodus', 6, 13, '&nbsp;مالِک خُدائ موسىٰ او هارون له حُکم ورکړو چې، ”بنى اِسرائيلو او د مِصر بادشاه فِرعون ته ووايئ چې ما تاسو له حُکم درکړے دے چې بنى اِسرائيل د مِصر نه بهر بوځئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1614, 'Exodus 6:14', 'Exodus', 6, 14, '&nbsp;د يعقوب د مشر زوئ، د روبين دا څلور زامن وُو، حنوک، فلو، حصرون او کرمى، دا د هغه قبيلو پلار نيکۀ وُو چې په دې نومونو ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1615, 'Exodus 6:15', 'Exodus', 6, 15, '&nbsp;د شمعون دا شپږ زامن وُو، يمو‌اېل، يمين، اُهد، يکين، صحر او ساؤل د کنعانۍ ښځې زوئ، دا د هغه قبيلو پلار نيکۀ وُو چې په دې نومونو ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1616, 'Exodus 6:16', 'Exodus', 6, 16, '&nbsp;د ليوى دا درې زامن وُو، جيرسون، قُهات او مرارى، دا د هغه قبيلو پلار نيکۀ وُو چې په دې نومونو ياديږى. د ليوى ټول عُمر يو سل اووۀ دېرش کاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1617, 'Exodus 6:17', 'Exodus', 6, 17, '&nbsp;د جيرسون دوه زامن وُو، لِبنى او سِمعى او د هغوئ ډېر اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1618, 'Exodus 6:18', 'Exodus', 6, 18, '&nbsp;د قُهات څلور زامن وُو، عُمرام، اِضهار، حبرون او عُزى‌اېل. د قُهات ټول عُمر يو سل درې دېرش کاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1619, 'Exodus 6:19', 'Exodus', 6, 19, '&nbsp;د مرارى دوه زامن وُو، محلى او موشى. دا د ليويانو قبيلې او اولاد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1620, 'Exodus 6:20', 'Exodus', 6, 20, '&nbsp;عُمرام د خپل پلار، خور يوکبد وادۀ کړه، چې د هغې نه يې هارون او موسىٰ پېدا شول. د عُمرام ټول عُمر يو سل اووۀ دېرش کاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1621, 'Exodus 6:21', 'Exodus', 6, 21, '&nbsp;د اِضهار درې زامن وُو، قورح، نفج او زِکرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1622, 'Exodus 6:22', 'Exodus', 6, 22, '&nbsp;د عُزى‌اېل هم درې زامن وُو، ميسائيل، الصفن او سترى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1623, 'Exodus 6:23', 'Exodus', 6, 23, '&nbsp;هارون د عمى‌نداب لور اليسبع وادۀ کړه چې هغه د نحشون خور وه، د هغې نه يې ندب، ابيهُو، اِلى‌عزر او اِتمر پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1624, 'Exodus 6:24', 'Exodus', 6, 24, '&nbsp;د قورح درې زامن وُو، اسير، القنه او ابياسف، دوئ د قورح قبيلو پلار نيکۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1625, 'Exodus 6:25', 'Exodus', 6, 25, '&nbsp;د هارون زوئ، اِلى‌عزر، د فوطئيل د لوڼو نه يوه لور وادۀ کړه، چې د هغې نه يې فينحاس پېدا شو. دا د ليوى قبيلې د قومونو او کورَنو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1626, 'Exodus 6:26', 'Exodus', 6, 26, '&nbsp;هارون او موسىٰ هغه کسان وُو چا ته چې مالِک خُدائ وفرمائيل چې، ”د بنى اِسرائيلو قبيلې د مِصر نه بهر بوځئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1627, 'Exodus 6:27', 'Exodus', 6, 27, '&nbsp;دا هغه کسان وُو چا چې د مِصر بادشاه فِرعون ته ووئيل چې بنى اِسرائيل د مِصر نه بهر تلو ته پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1628, 'Exodus 6:28', 'Exodus', 6, 28, '&nbsp;چې کله مالِک خُدائ د مِصر په مُلک کښې موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1629, 'Exodus 6:29', 'Exodus', 6, 29, '&nbsp;”زۀ مالِک خُدائ يم. چې زۀ تا ته څۀ وايم هغه هر څۀ د مِصر بادشاه فِرعون ته ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1630, 'Exodus 6:30', 'Exodus', 6, 30, '&nbsp;خو موسىٰ مالِک خُدائ ته وفرمائيل، ”تا ته پته ده چې زۀ په خبرو کولو کښې تکړه نۀ يم، نو فِرعون به زما خبره څنګه واورى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1631, 'Exodus 7:1', 'Exodus', 7, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”ګوره، زۀ تا فِرعون ته د خُدائ په شان جوړوم او ستا ورور هارون به ستا د پېغمبر په توګه د هغۀ سره خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1632, 'Exodus 7:2', 'Exodus', 7, 2, '&nbsp;چې څنګه ما حُکم درکړے دے هارون ته هغه هر څۀ ووايه او هغه به فِرعون ته ووائى چې بنى اِسرائيل د هغۀ د مُلک نه تلو ته پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1633, 'Exodus 7:5', 'Exodus', 7, 5, '&nbsp;نو مِصريانو ته به پته ولګى چې زۀ مالِک خُدائ يم، چې کله زۀ د دوئ خِلاف خپل لاس اوچت کړم نو بنى اِسرائيل د هغوئ د مُلک نه بهر بوځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1634, 'Exodus 7:6', 'Exodus', 7, 6, '&nbsp;موسىٰ او هارون هم هغسې وکړل، لکه څنګه چې مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1635, 'Exodus 7:7', 'Exodus', 7, 7, '&nbsp;په هغه وخت چې کله دوئ فِرعون سره خبرې وکړې، موسىٰ د اتياو کالو وو او هارون د درې اتياو کالو وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1636, 'Exodus 7:8', 'Exodus', 7, 8, '&nbsp;مالِک خُدائ موسىٰ او هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1637, 'Exodus 7:9', 'Exodus', 7, 9, '&nbsp;”کله چې فِرعون تاسو ته ووائى چې تاسو يوه معجزه ښکاره کړئ، نو هارون ته ووايه چې خپله امسا راواخلى او د فِرعون په مخکښې يې وغورزوى، نو يو مار به ترې نه جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1638, 'Exodus 7:10', 'Exodus', 7, 10, '&nbsp;نو موسىٰ او هارون فِرعون له لاړل او هغه شان يې وکړل چې څنګه مالِک خُدائ حُکم ورکړے وو. هارون خپله امسا د فِرعون او د هغۀ د درباريانو په مخکښې وغورزوله، نو يو مار ترې نه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1639, 'Exodus 7:11', 'Exodus', 7, 11, '&nbsp;نو فِرعون هم خپل د غېب عِلم لرونکى خلق او جادوګران راوغوښتل او هغوئ هم د جادو په ذريعه هم هغه شان وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1640, 'Exodus 7:12', 'Exodus', 7, 12, '&nbsp;هغوئ خپلې امساګانې وغورزولې او د امساګانو نه ماران جوړ شول. خو د هارون امسا د هغوئ امساګانې تېرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1641, 'Exodus 7:13', 'Exodus', 7, 13, '&nbsp;خو د فِرعون زړۀ تر اوسه پورې سخت وو. لکه څنګه چې مالِک خُدائ فرمائيلى وُو، هغۀ به د موسىٰ او هارون خبره نۀ اورېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1642, 'Exodus 7:14', 'Exodus', 7, 14, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”د فِرعون زړۀ سخت دے، هغه خلق تلو ته نۀ پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1643, 'Exodus 7:15', 'Exodus', 7, 15, '&nbsp;په سحر کښې فِرعون له لاړ شه چې کله هغه د نيل درياب ته کوزيږى. د خپل ځان سره هغه امسا هم يوسه چې مار ترې نه جوړ شوے وو او د درياب په غاړه هغۀ ته ودرېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1644, 'Exodus 7:16', 'Exodus', 7, 16, '&nbsp;بيا فِرعون ته ووايه چې مالِک خُدائ د عبرانيانو خُدائ پاک، زۀ رالېږلے يم چې تا ته ووايم چې د هغۀ خلق تلو ته پرېږده چې دوئ په صحرا کښې د هغۀ عبادت وکړى. خو ګوره، تا تر اوسه پورې دا خبره ونۀ منله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1645, 'Exodus 7:17', 'Exodus', 7, 17, '&nbsp;نو اوس، بادشاه سلامت، مالِک خُدائ به يو داسې کار وکړى چې تا ته پته ولګى چې هغه په رښتيا مالِک خُدائ دے. ګوره، زما په لاس کښې چې کومه امسا ده زۀ د درياب اوبۀ په دې وهم او د اوبو نه به وينه جوړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1646, 'Exodus 7:18', 'Exodus', 7, 18, '&nbsp;کبان به مړۀ شى او د درياب اوبۀ به دومره سخت بوئ شروع کړى چې مِصريان به ترې اوبۀ نۀ شى څښلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1647, 'Exodus 7:19', 'Exodus', 7, 19, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”هارون ته ووايه چې خپله امسا راواخلى او د مِصر ټولو اوبو په طرف يعنې دريابونو، نِهرونو او ډنډونو دپاسه ونيسى. نو د اوبو نه به وينه جوړه شى او د مِصر په ټوله زمکه به وينه وى، داسې د لرګى په لوښو او د خټې په منګو کښې به هم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1648, 'Exodus 7:20', 'Exodus', 7, 20, '&nbsp;نو موسىٰ او هارون هم هغسې وکړل چې څنګه مالِک خُدائ حُکم کړے وو. د فِرعون او د هغۀ درباريانو په مخکښې، هارون خپله امسا اوچته کړه او د درياب اوبۀ يې پرې ووهلې او د درياب د ټولو اوبو نه وينه جوړه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1649, 'Exodus 7:21', 'Exodus', 7, 21, '&nbsp;په درياب کښې کبان مړۀ شول او دومره سخا بوئ يې کولو چې مِصريانو د درياب نه اوبۀ نۀ شوې څښلے. او د مِصر په ټول مُلک کښې وينه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1650, 'Exodus 7:22', 'Exodus', 7, 22, '&nbsp;بيا د فِرعون جادوګرانو د خپل جادو په ذريعه هم دغه شان وکړل او د فِرعون زړۀ هم هغه شان سخت وو. لکه څنګه چې مالِک خُدائ فرمائيلى وُو، هغۀ د موسىٰ او هارون د خبرې اورېدو نه اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1651, 'Exodus 7:23', 'Exodus', 7, 23, '&nbsp;فِرعون راوګرځېدو او خپل محل ته لاړو، دا خبره يې زړۀ ته ښکته نۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
