(1653, 'Exodus 7:25', 'Exodus', 7, 25, '&nbsp;چې مالِک خُدائ په درياب افت راوستلے وو نو اووۀ ورځې د هغې نه پس تېرې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1654, 'Exodus 8:1', 'Exodus', 8, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”فِرعون له ورشه او هغۀ ته ووايه چې مالِک خُدائ فرمائى، زما خلق تلو ته پرېږده چې دوئ زما عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1655, 'Exodus 8:2', 'Exodus', 8, 2, '&nbsp;کۀ تا اِنکار وکړو، نو زۀ به ستا په ټول مُلک داسې افت راولم چې په چيندخو به يې پټ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1656, 'Exodus 8:3', 'Exodus', 8, 3, '&nbsp;د نيل درياب به د بې‌شمېره چيندخو نه ډک وى. دا به ستا محل، ستا د څملاستو کوټې او کټ ته، ستا د درباريانو او د خلقو کورونو ته او ستاسو تنورونو او د اوړو ښانکونو ته به هم دروخېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1657, 'Exodus 8:4', 'Exodus', 8, 4, '&nbsp;چيندخې به په تا، ستا په خلقو او ستا په ټولو درباريانو دروخېژى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1658, 'Exodus 8:5', 'Exodus', 8, 5, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”هارون ته ووايه چې خپله امسا د دريابونو، نِهرونو او ډنډونو دپاسه ونيسه او چيندخې به د مِصر په مُلک وروخېژوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
