(1667, 'Exodus 8:14', 'Exodus', 8, 14, '&nbsp;مِصريانو دا راغونډې کړې او لوئ ډېرى يې ترې جوړ کړل او ټول مُلک سخا بوئ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1668, 'Exodus 8:15', 'Exodus', 8, 15, '&nbsp;فِرعون چې کله دا وليدل چې خېر شو، نو هغۀ بيا خپل زړۀ سخت کړو، لکه څنګه چې مالِک خُدائ فرمائيلى وُو، چې فِرعون به د موسىٰ او هارون خبره نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1669, 'Exodus 8:16', 'Exodus', 8, 16, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”هارون ته ووايه چې زمکه په خپله امسا ووهه، نو د ټول مِصر د مُلک خاورې نه به ماشى جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
