(1681, 'Exodus 8:28', 'Exodus', 8, 28, '&nbsp;نو فِرعون ووئيل، ”زۀ به تاسو تلو ته پرېږدم چې مالِک خُدائ، خپل خُدائ پاک ته په صحرا کښې قربانۍ پېش کړئ، خو تاسو ډېر لرې مۀ ځئ. زما دپاره سوال وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1682, 'Exodus 8:29', 'Exodus', 8, 29, '&nbsp;موسىٰ ورته وفرمائيل، ”چې څنګه زۀ لاړ شم، نو زۀ به مالِک خُدائ ته سوال وکړم چې سبا ستا، ستا د درباريانو او ستا د خلقو نه مچان لاړ شى. خو چې بيا تۀ مونږ له دوکه رانۀ کړې او چې خلق د تلو نه ايسار نۀ کړې چې مالِک خُدائ ته قربانۍ وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1683, 'Exodus 8:30', 'Exodus', 8, 30, '&nbsp;موسىٰ د فِرعون د دربار نه لاړو او مالِک خُدائ ته يې سوال وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
