(1691, 'Exodus 9:6', 'Exodus', 9, 6, '&nbsp;بله ورځ مالِک خُدائ هم هغسې وکړل لکه څنګه چې مالِک خُدائ فرمائيلى وُو. د مِصريانو ټول څاروى مړۀ شول، خو د بنى اِسرائيلو يو څاروے هم مړ نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1692, 'Exodus 9:7', 'Exodus', 9, 7, '&nbsp;فِرعون تپوس وکړو چې څۀ شوى وُو او هغۀ ته ووئيلے شول چې د بنى اِسرائيلو يو څاروے هم مړ نۀ شو. خو د هغۀ زړۀ سخت وو او هغۀ به خلق تلو ته نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1693, 'Exodus 9:8', 'Exodus', 9, 8, '&nbsp;بيا مالِک خُدائ موسىٰ او هارون ته وفرمائيل، ”د بټۍ نه يو څو لَپې ايرې راواخلئ، دا به موسىٰ د فِرعون په مخکښې د آسمان طرف ته لړه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1694, 'Exodus 9:9', 'Exodus', 9, 9, '&nbsp;دا به د دوړې په شان د مِصر په ټول مُلک کښې خورې شى او په هر ځائ کښې به دا دانې په خلقو او ځناورو راوخېژى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1695, 'Exodus 9:10', 'Exodus', 9, 10, '&nbsp;نو هغوئ ايرې راواخستلې او د فِرعون په مخکښې ودرېدل، موسىٰ دا د آسمان طرف ته لړه کړې، نو په خلقو او ځناورو باندې دانې راوختلې او سخا شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1696, 'Exodus 9:11', 'Exodus', 9, 11, '&nbsp;جادوګران د دې قابل نۀ وُو چې د موسىٰ په مخکښې ولاړ وے، ځکه چې د نورو ټولو مِصريانو په شان دوئ هم په دانو پټ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1697, 'Exodus 9:12', 'Exodus', 9, 12, '&nbsp;خو مالِک خُدائ د فِرعون زړۀ سخت کړو، لکه څنګه چې هغۀ فرمائيلى وُو، چې فِرعون به د موسىٰ او هارون خبره نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1698, 'Exodus 9:13', 'Exodus', 9, 13, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”سحر وختى پاڅه او د فِرعون په مخکښې ودرېږه او هغۀ ته ووايه چې مالِک خُدائ، د عبرانيانو خُدائ پاک فرمائى، چې زما خلق تلو ته پرېږده چې دوئ زما عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1699, 'Exodus 9:14', 'Exodus', 9, 14, '&nbsp;دا ځل به زۀ نۀ صِرف ستا درباريانو او ستا خلقو له سزا ورکوم، بلکې دغه شان تا له به هم سزا درکوم، نو تا ته به پته ولګى چې په ټوله دُنيا کښې زما په شان بل هيڅ څوک هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1700, 'Exodus 9:15', 'Exodus', 9, 15, '&nbsp;کۀ ما خپل لاس اوچت کړے وے او تۀ او ستا خلق مې په بيمارو وهلے وے، نو تاسو به د دُنيا نه ورک شوى وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');